package android.app;
public abstract class Service extends android.content.ContextWrapper implements android.content.ComponentCallbacks2 { public static final int START_STICKY=1, START_NOT_STICKY=2, START_REDELIVER_INTENT=3; public Service() { super(null); } public void onCreate() {} public int onStartCommand(android.content.Intent i,int flags,int startId) { return START_STICKY; } public abstract android.os.IBinder onBind(android.content.Intent i); public boolean onUnbind(android.content.Intent i) { return false; } public void onRebind(android.content.Intent i) {} public void onDestroy() {} public void onConfigurationChanged(android.content.res.Configuration c) {} public void onLowMemory() {} public void onTrimMemory(int level) {} public void stopSelf() {} public void stopSelf(int id) {} public boolean stopSelfResult(int id) { return true; } public void startForeground(int id,Notification notification) {} public void stopForeground(boolean remove) {} }
